import { detectCoarsePointer } from './orbitSpeed';

/**
 * 高配 / 低配两档模型。
 *
 * 现场反馈："手机端左右移动很卡，宽屏和网页端不会"。原因是**几何量**：场地模型 910 万三角面、
 * 363 个图元（314 个材质），设备页的变压器 379 万面、312 个图元。桌面独显（实测 RTX 4060 Laptop）
 * 一帧只要几毫秒，手机 GPU 的顶点吞吐和 draw call 开销是它的十几到几十分之一，同样的场景就是一帧
 * 几十毫秒 —— 而且左右旋转时整个场地都会扫进视锥，逐帧都是全量开销，所以**水平拖动最卡**。
 *
 * 分辨率已经不是瓶颈：手机档 `pixelRatio` 本来就锁在 1（画布约 0.33 Mpx，比桌面的 1.3 Mpx 还小），
 * 再降只会糊；所以低配档换的是**模型本身**（面数约 1/4~1/5，文件也小 35%~55%）。
 *
 * 判定用主指针而不是 `maxTouchPoints`：带触摸屏的 Windows 笔记本主指针是鼠标，
 * 不该被降级（与 `shared/orbitSpeed.ts` 的粗指针判定同一套）。
 */
export type ModelQuality = 'high' | 'low';

export const MODEL_QUALITY_PARAM = 'quality';

/** `?quality=low|high` 强制档位（真机对比用）；其它值当作没写。 */
export function readQualityOverride(search: string): ModelQuality | null {
  const value = new URLSearchParams(search).get(MODEL_QUALITY_PARAM);
  return value === 'low' || value === 'high' ? value : null;
}

export interface QualityProbe {
  /** 覆盖参数，通常是 `window.location.search`。 */
  search?: string;
  /** 主指针是否手指。 */
  coarsePointer?: boolean;
  /** `navigator.connection.saveData`（省流量模式）。 */
  saveData?: boolean;
  /** 当前视口宽度，用于兜底判断"小屏"（jsdom 里 matchMedia 不一定可靠）。 */
  viewportWidth?: number;
}

/**
 * 是否走低配模型。顺序：`?quality=` 覆盖 → 省流量 → 主指针是手指。
 * 只在"手指设备"上降级，桌面上（哪怕屏幕小）始终拿完整模型。
 */
export function prefersLowPowerModel(probe: QualityProbe = {}): boolean {
  const search = probe.search ?? (typeof window === 'undefined' ? '' : window.location.search);
  const override = readQualityOverride(search);
  if (override) return override === 'low';

  const saveData = probe.saveData ?? readSaveData();
  if (saveData) return true;

  const coarse = probe.coarsePointer ?? detectCoarsePointer();
  if (!coarse) return false;

  const width = probe.viewportWidth ?? (typeof window === 'undefined' ? Number.POSITIVE_INFINITY : window.innerWidth);
  return Number.isFinite(width) ? width <= 1440 : true;
}

function readSaveData(): boolean {
  if (typeof navigator === 'undefined') return false;
  const connection = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  return connection?.saveData === true;
}

/** 从来源里挑出该用的 URL：没有低配档、或当前是高配档，就用原始 URL。 */
export function pickModelUrl(
  source: { url: string; lowPowerUrl?: string },
  lowPower = prefersLowPowerModel(),
): string {
  return lowPower && source.lowPowerUrl ? source.lowPowerUrl : source.url;
}
