/**
 * 三维舞台的配色（precision · 浅色纸面方案）。
 *
 * `DeviceScene` / `SiteScene` / `SiteOverlay3D` 三个场景都经 `activeScenePalette()` 取一套配色，
 * 于是"换舞台味道"只改这一个文件，场景组件不必知道配色从哪里来。
 *
 * 数值来源与理由：
 * - `BASE_SCENE_PALETTE` 是那套原有的浅色舞台值（白色台面 + 柔光 + RoomEnvironment 全强度）——
 *   它本来就是为浅色界面调的，precision 的纸面舞台直接以它为底。
 * - precision 只替换与"纸面"直接相邻的几项：清屏色取纸白、台面偏暖、两圈参考线取蓝图蓝、选中高亮取品牌青绿。
 * - 实测：舞台亮度由 `RoomEnvironment` 的 IBL 主导，只压方向光往往没有反应，要压暗得连
 *   `environmentIntensity` 与色调映射（ACESFilmic）一起校。
 */
export interface DeviceScenePalette {
  clearColor: number;
  exposure: number;
  environmentIntensity: number;
  hemisphere: { sky: number; ground: number; intensity: number };
  key: { color: number; intensity: number; position: [number, number, number] };
  rim: { color: number; intensity: number; position: [number, number, number] };
  ground: { color: number; roughness: number };
  platform: { color: number; metalness: number; roughness: number };
  ring: { color: number; opacity: number };
  innerRing: { color: number; opacity: number };
  selectedEmissive: number;
}

export interface SiteScenePalette {
  sky: number;
  exposure: number;
  environmentIntensity: number;
  fog: { near: number; far: number };
  hemisphere: { sky: number; ground: number; intensity: number };
  key: { color: number; intensity: number; position: [number, number, number] };
  fill: { color: number; intensity: number; position: [number, number, number] };
}

export interface ScenePalette {
  device: DeviceScenePalette;
  site: SiteScenePalette;
}

/** 浅色舞台底：precision 的纸面舞台以它为底（只替换下面那几项）。 */
export const BASE_SCENE_PALETTE: ScenePalette = Object.freeze<ScenePalette>({
  device: {
    clearColor: 0xf2f3f3,
    exposure: 1.08,
    environmentIntensity: 1,
    hemisphere: { sky: 0xffffff, ground: 0xa7acb2, intensity: 1.05 },
    key: { color: 0xfffaf4, intensity: 2.3, position: [-3, 7, 5] },
    rim: { color: 0xe9f4ff, intensity: 1.7, position: [4, 3, -4] },
    ground: { color: 0xd8dcdf, roughness: 1 },
    platform: { color: 0xeeeeec, metalness: 0.12, roughness: 0.67 },
    ring: { color: 0x8c969f, opacity: 0.38 },
    innerRing: { color: 0xa4aeb8, opacity: 0.18 },
    selectedEmissive: 0x276d68,
  },
  site: {
    sky: 0xdde5e9,
    exposure: 1.05,
    environmentIntensity: 1,
    fog: { near: 520, far: 2200 },
    hemisphere: { sky: 0xf2f7fa, ground: 0x9aa3a6, intensity: 1.15 },
    key: { color: 0xfff6e8, intensity: 1.85, position: [-120, 220, 160] },
    fill: { color: 0xdfeaf5, intensity: 0.75, position: [180, 90, -140] },
  },
});

/**
 * precision（浅色纸面方案）的三维舞台配色。
 *
 * 思路：**沿用那套亮色灯光与曝光**（它本来就是为浅色界面调的），只把"舞台本身"换成 precision 的纸面语言：
 * - 清屏色取与页面完全相同的纸白 `#f8f6ef`，画布与纸面之间不再出现一道冷灰边界（原先最明显的不协调）；
 * - 转盘的两圈参考线与蓝图母题同色（`#648f98` / `#9eb8bb`，见 precision 的 `.precision-blueprint`）；
 * - 选中高亮用 precision 的唯一品牌色 `#1d696a`。
 */
export const PRECISION_SCENE_PALETTE: ScenePalette = Object.freeze<ScenePalette>({
  device: {
    ...BASE_SCENE_PALETTE.device,
    clearColor: 0xf8f6ef,
    ground: { color: 0xe4e0d5, roughness: 1 },
    platform: { color: 0xf2f0e8, metalness: 0.12, roughness: 0.67 },
    ring: { color: 0x648f98, opacity: 0.42 },
    innerRing: { color: 0x9eb8bb, opacity: 0.24 },
    selectedEmissive: 0x1d696a,
  },
  site: {
    ...BASE_SCENE_PALETTE.site,
    sky: 0xf2efe6,
  },
});

/** 当前舞台配色。应用只保留 precision 一套 UI，因此这里恒为纸面方案；
 *  保留函数形式是为了让场景组件继续走同一个取色入口（将来若要加日间/夜间变体只改这里）。 */
export function activeScenePalette(): ScenePalette {
  return PRECISION_SCENE_PALETTE;
}
