/**
 * OrbitControls 的旋转灵敏度是「每像素位移 → 固定弧度」，而这个换算的分母是**画布高度**：
 *
 * ```js
 * _rotateDelta.subVectors(_rotateEnd, _rotateStart).multiplyScalar(this.rotateSpeed);
 * _rotateLeft(_twoPI * _rotateDelta.x / element.clientHeight);  // OrbitControls.js:1109，原注释就是 "yes, height"
 * ```
 *
 * 即 `rad/px = rotateSpeed * 2π / 画布高`。画布越高越钝：
 * 桌面 1440×900 的画布高约 822px（实测 0.0042 rad/px），
 * 平板竖屏 820×1180 的画布高约 1102px（实测 0.0031 rad/px，**低 25%**）——
 * 现场反馈"手机/平板左右拖一次只移动一点点"里，平板这一份就是这条：
 * 同样的手指位移，平板转过的角度天生比桌面小四分之一。
 *
 * 这里把**粗指针（手指）**设备的 rotateSpeed 按画布高度等比补偿回桌面基准，
 * 并且**只增不减**：手机画布（约 773px）本来就落在"偏灵敏"那一侧（实测 0.0045 rad/px），
 * 若一起等比缩小会朝着现场抱怨的方向走，所以下限锁 1（手机、桌面手感完全不变），
 * 上限 1.4 防止超大画布上一根手指扫过去就飞出去。
 */
export const ROTATE_SPEED_REFERENCE_HEIGHT = 822;
export const ROTATE_SPEED_MAX_SCALE = 1.4;

export function coarseRotateSpeedScale(
  canvasHeight: number,
  isCoarsePointer: boolean,
  reference = ROTATE_SPEED_REFERENCE_HEIGHT,
  max = ROTATE_SPEED_MAX_SCALE,
): number {
  if (!isCoarsePointer) return 1;
  if (!Number.isFinite(canvasHeight) || canvasHeight <= 0) return 1;
  return Math.min(Math.max(canvasHeight / reference, 1), max);
}

/**
 * 是否以手指为主指针。用 `(pointer: coarse)` 而不是 `maxTouchPoints`：
 * 带触摸屏的 Windows 笔记本同时有鼠标/触控板，主指针是 fine，不该被放大。
 */
export const detectCoarsePointer = (): boolean => {
  if (typeof window === 'undefined') return false;
  if (typeof window.matchMedia === 'function') return window.matchMedia('(pointer: coarse)').matches;
  return (navigator.maxTouchPoints ?? 0) > 0;
};
