/**
 * 模型文件的持久缓存（Cache Storage）。
 *
 * 现场要求：**两台设备模型、场地模型以及各类文件要缓存起来，避免重复下载**。
 *
 * 为什么模型要由**页面自己**缓存，而不是交给 Service Worker：
 *   发布包的 `sw.js`（见 `static-deploy-package/sw.js`）**刻意不拦截 `/content/*`**。
 *   2026-09-24 修线上问题时查明：设备页的"正在准备 x%"完全依赖 `ProgressEvent.loaded/total`，
 *   而 WebKit 在**经 Service Worker 应答的下载**里会丢失进度事件（WebKit #256696 / #258412），
 *   于是 iPhone 上进度永远到不了 100%、加载卡片不消失；`response.clone()` 还会把 39 MB 响应
 *   在内存里再存一份，而此刻 WebGL 正在分配数百 MB 贴图。**所以 `/content/*` 必须留给网络。**
 *
 *   模型由页面侧来缓存就没有这两个问题：字节本来就是页面自己下下来的（分块并发，进度由
 *   `chunkedDownload` 自己算，不依赖 ProgressEvent），缓存命中时更是**一个请求都不发**。
 *   浏览器 HTTP 缓存也帮不上忙：`content/*` 只有 10 分钟 `max-age`，而大模型走 Range 分段请求
 *   （见 `chunkedDownload.ts`），206 按段缓存、极易失效 —— 来回切页面就会反复重下。
 *
 * 缓存是"锦上添花"：不安全上下文（`file://`）、jsdom、配额不足、隐私模式下一律**静默退化成
 * 直连网络**，绝不让缓存本身把加载搞挂。
 *
 * 开发提示：素材文件名一律带版本号（`…-v20260922.glb` / `…-20261015.glb`），换素材时改的是**文件名**，
 * 因此 url 变了、缓存自然失效。如果就地覆盖了同名文件而页面还显示旧模型，清一下站点的
 * Cache Storage 即可 —— 这是版本化命名换来的确定性。
 */

/**
 * 缓存名。**必须用 `museum-assets-v1`**：发布包的 `sw.js` 在 `activate` 里只保留
 * `museum-content-<BUILD>` 与 `museum-assets-v1`，**其余缓存一律删除**。
 * 换成别的名字，模型缓存会在每次发布后被 SW 清掉（等于白缓存）；用这个名字则跨发布保留，
 * 与 SW 写入的 `/assets/`（内容哈希命名）共存互不干扰。
 */
export const ASSET_CACHE_NAME = 'museum-assets-v1';

/** 当前环境有没有可用的 Cache Storage（https / localhost 才有；`file://` 与 jsdom 没有）。 */
function cacheStorage(): CacheStorage | null {
  if (typeof window === 'undefined') return null;
  const storage = (window as Window & { caches?: CacheStorage }).caches;
  return storage && typeof storage.open === 'function' ? storage : null;
}

export function isAssetCacheAvailable(): boolean {
  return cacheStorage() !== null;
}

/**
 * 缓存键统一成**绝对 URL**。
 *
 * 应用里的素材地址是相对的（`resolveAssetUrl` 直接给 `./content/xxx.glb`，见 `config/loadConfig.ts`），
 * 而 Service Worker 那边拿到的是浏览器解析好的绝对 URL。两边都归一到绝对 URL，
 * 才能命中同一份缓存（`Cache.put/match` 对字符串键也是按绝对 URL 比的）。
 */
function cacheKey(url: string): string {
  try {
    return new URL(url, window.location.href).href;
  } catch {
    return url;
  }
}

async function openCache(): Promise<Cache | null> {
  const storage = cacheStorage();
  if (!storage) return null;
  try {
    return await storage.open(ASSET_CACHE_NAME);
  } catch {
    // 不安全上下文、配额被拒、用户禁用存储……都退化成"没有缓存"。
    return null;
  }
}

/** 读缓存里的整份响应；没命中或不可用时返回 `null`。 */
export async function readCachedAsset(url: string): Promise<Response | null> {
  const cache = await openCache();
  if (!cache) return null;
  try {
    return (await cache.match(cacheKey(url))) ?? null;
  } catch {
    return null;
  }
}

/** 读缓存里的整份资源字节；没命中时返回 `null`。 */
export async function readCachedBuffer(url: string): Promise<ArrayBuffer | null> {
  const response = await readCachedAsset(url);
  if (!response) return null;
  try {
    return await response.arrayBuffer();
  } catch {
    return null;
  }
}

/**
 * 把整份响应写进缓存。任何失败（配额、不可缓存）都吞掉 —— 调用方不该因为它中断。
 */
export async function writeCachedAsset(url: string, response: Response): Promise<boolean> {
  const cache = await openCache();
  if (!cache) return false;
  try {
    await cache.put(cacheKey(url), response);
    return true;
  } catch {
    return false;
  }
}

/** 把整份资源字节写进缓存（模型加载完成后回填用）。 */
export async function writeCachedBuffer(url: string, buffer: ArrayBuffer, contentType = 'application/octet-stream'): Promise<boolean> {
  return writeCachedAsset(url, new Response(buffer, { headers: { 'Content-Type': contentType } }));
}

/**
 * 缓存优先地取整份资源字节：命中直接返回（**不发网络请求**），否则单请求拉一份并回填缓存。
 *
 * `onProgress` 只在真正走网络时有意义（命中缓存直接报 100）。
 * 返回 `null` 表示"缓存不可用且请求失败"——调用方应退回各自的原始加载路径。
 */
export async function fetchCachedBuffer(
  url: string,
  { onProgress }: { onProgress?: (percent: number) => void } = {},
): Promise<ArrayBuffer | null> {
  const cached = await readCachedBuffer(url);
  if (cached) {
    onProgress?.(100);
    return cached;
  }
  try {
    const response = await fetch(url);
    if (!response.ok) return null;
    onProgress?.(100);
    const buffer = await response.arrayBuffer();
    // 回填缓存；不 await —— 用户不该为了"存一份备份"多等一次写盘。
    void writeCachedBuffer(url, buffer, contentTypeOf(url));
    return buffer;
  } catch {
    return null;
  }
}

/** 按扩展名给个像样的 Content-Type（缓存里的响应将来可能被 `<img>`/pdf.js 直接读取）。 */
function contentTypeOf(url: string): string {
  const path = url.split('?')[0]?.toLowerCase() ?? '';
  if (path.endsWith('.glb') || path.endsWith('.gltf')) return 'model/gltf-binary';
  if (path.endsWith('.pdf')) return 'application/pdf';
  if (path.endsWith('.jpg') || path.endsWith('.jpeg')) return 'image/jpeg';
  if (path.endsWith('.png')) return 'image/png';
  if (path.endsWith('.webp')) return 'image/webp';
  if (path.endsWith('.mp4')) return 'video/mp4';
  return 'application/octet-stream';
}
