import { Box3, Mesh, type Object3D } from 'three';
import type { DevicePartConfig } from '../../config/schema';

export interface PartBinding {
  part: DevicePartConfig;
  objects: Object3D[];
  meshes: Set<Mesh>;
  origins: Array<Object3D['position']>;
  originalVisibility?: boolean[];
}

export interface PartBindingIssue {
  partId: string;
  nodeName: string;
}

export function getObjectsBounds(objects: Object3D[]): Box3 | null {
  const bounds = new Box3();
  for (const object of objects) {
    object.updateWorldMatrix(true, true);
    bounds.expandByObject(object, true);
  }
  return bounds.isEmpty() ? null : bounds;
}

export function bindConfiguredParts(root: Object3D, parts: DevicePartConfig[]) {
  const issues: PartBindingIssue[] = [];
  const bindings = new Map<string, PartBinding>();
  for (const part of parts) {
    const objects = part.nodeNames.flatMap(nodeName => {
      const object = root.getObjectByName(nodeName);
      if (!object) issues.push({ partId: part.id, nodeName });
      return object ? [object] : [];
    });
    if (objects.length) {
      const meshes = new Set<Mesh>();
      for (const object of objects) object.traverse(child => { if (child instanceof Mesh) meshes.add(child); });
      bindings.set(part.id, {
        part,
        objects,
        meshes,
        origins: objects.map(object => object.position.clone()),
        originalVisibility: objects.map(object => object.visible),
      });
    }
  }
  return { bindings, issues };
}
