/**
 * 大模型文件的**分块并发下载**。
 *
 * 为什么需要它：GitHub Pages（以及其他不少静态托管）对**单条 TCP 连接**限速。
 * 2026-10-19 实测 `content/wugao-site-full-v20260923.glb`（33 MB）：
 *
 * | 并发连接数 | 聚合吞吐 | 33 MB 需要 |
 * |---|---|---|
 * | 1 | 37 KB/s | ≈ 15 分钟 |
 * | 2 | 67 KB/s | ≈ 8 分钟 |
 * | 4 | 140 KB/s | ≈ 4 分钟 |
 * | 8 | 247 KB/s | ≈ 2.2 分钟 |
 *
 * 也就是说瓶颈在**每条连接**（约 31 KB/s），而不是用户带宽 —— 现场反馈"网速并没有那么慢，
 * 但模型加载太慢"正是这个原因。`Accept-Ranges: bytes` 是 GitHub Pages 一直带上的响应头，
 * 所以这里用 Range 请求把同一个文件切成若干段并发拉，再拼回一个 ArrayBuffer 交给
 * `GLTFLoader.parse()`；任何一步不符合预期（不支持 Range、返回 200、分块失败）都返回
 * `null` / 抛错，由调用方退回原来的单请求 `loader.load()`。
 *
 * 刻意**总是**走分块路径（而不是"先单请求、慢了再换"）：HTTP 缓存对 206 响应是按段缓存的，
 * 两条路径来回切会让缓存完全失效；固定一条路径时，重复访问仍能命中同一批分段缓存。
 */

/** 低于这个大小就不折腾了：小文件单请求更快，也没有限速问题。 */
export const CHUNKED_MIN_BYTES = 4 * 1024 * 1024;
/** 并发连接数。浏览器对同源 HTTP/1.1 一般允许 6 条，再多只会排队。 */
export const CHUNKED_CONCURRENCY = 6;

export interface ChunkedDownloadOptions {
  /** 进度回调，与 `XMLHttpRequest` 的语义一致：0–100 的整数百分比。 */
  onProgress?: (percent: number) => void;
  concurrency?: number;
  minBytes?: number;
  /** 便于单测注入。 */
  fetcher?: typeof fetch;
}

interface Probe {
  total: number;
}

/**
 * 用 1 字节的 Range 请求探一次：既能确认服务端支持 Range，又能拿到文件总长。
 * 不支持（忽略 Range 返回 200、没有 content-range、跨域被拦）时返回 null。
 */
async function probe(fetcher: typeof fetch, url: string): Promise<Probe | null> {
  const response = await fetcher(url, { headers: { Range: 'bytes=0-0' } });
  if (response.status !== 206) {
    // 服务端忽略了 Range（200 会把整个文件吐出来）——立刻掐断，别白下 33MB。
    void response.body?.cancel().catch(() => {});
    return null;
  }
  const contentRange = response.headers.get('content-range') ?? '';
  const total = Number(contentRange.split('/')[1]);
  void response.body?.cancel().catch(() => {});
  return Number.isFinite(total) && total > 0 ? { total } : null;
}

/** 下载单段；写入调用方给的目标缓冲区，边下边回报字节数。 */
async function downloadRange(
  fetcher: typeof fetch,
  url: string,
  start: number,
  end: number,
  sink: Uint8Array,
  onBytes: (count: number) => void,
): Promise<void> {
  const response = await fetcher(url, { headers: { Range: `bytes=${start}-${end}` } });
  if (response.status !== 206 || !response.body) {
    void response.body?.cancel().catch(() => {});
    throw new Error(`分块下载失败：HTTP ${response.status}`);
  }
  const reader = response.body.getReader();
  let offset = start;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!value?.length) continue;
    if (offset + value.length > end + 1) throw new Error('分块下载越界：服务端返回了多余的字节');
    sink.set(value, offset);
    offset += value.length;
    onBytes(value.length);
  }
  if (offset !== end + 1) throw new Error(`分块下载不完整：期望 ${end - start + 1} 字节，实际 ${offset - start}`);
}

/**
 * 分块并发下载；不适用或失败时返回 `null`，调用方应退回单请求下载。
 *
 * @returns 完整文件的 `ArrayBuffer`；不适用时 `null`（并非错误）。
 */
export async function fetchInChunks(url: string, options: ChunkedDownloadOptions = {}): Promise<ArrayBuffer | null> {
  const fetcher = options.fetcher ?? fetch;
  const concurrency = Math.max(2, options.concurrency ?? CHUNKED_CONCURRENCY);
  const minBytes = options.minBytes ?? CHUNKED_MIN_BYTES;

  // 省流模式（`navigator.connection.saveData`）下不要并发抢占带宽。
  const connection = typeof navigator === 'undefined'
    ? undefined
    : (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  if (connection?.saveData) return null;

  const probed = await probe(fetcher, url);
  if (!probed) return null;
  const { total } = probed;
  if (total < minBytes) return null;

  const buffer = new Uint8Array(total);
  let received = 0;
  let reported = -1;
  const report = () => {
    const percent = Math.min(100, Math.round(received / total * 100));
    if (percent !== reported) {
      reported = percent;
      options.onProgress?.(percent);
    }
  };

  const chunkSize = Math.ceil(total / concurrency);
  const jobs: Array<{ start: number; end: number }> = [];
  for (let start = 0; start < total; start += chunkSize) {
    jobs.push({ start, end: Math.min(total - 1, start + chunkSize - 1) });
  }

  // 逐段带一次重试：弱网下单段偶发失败不该让整次加载退化回单连接。
  const runJob = async (job: { start: number; end: number }) => {
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        await downloadRange(fetcher, url, job.start, job.end, buffer, count => { received += count; report(); });
        return;
      } catch (error) {
        if (attempt === 1) throw error;
      }
    }
  };

  // 并发度受控：每次最多 concurrency 段同时在跑。
  let cursor = 0;
  const workers = Array.from({ length: Math.min(concurrency, jobs.length) }, async () => {
    for (;;) {
      const job = jobs[cursor];
      cursor += 1;
      if (!job) return;
      await runJob(job);
    }
  });
  await Promise.all(workers);
  options.onProgress?.(100);
  return buffer.buffer;
}
